// LAB: Traverse empty and nonempty ranges
// Implement a bounded sum using vector iterators. Use a wide accumulator for this small-int fixture and support an empty range without dereferencing its end.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    const int values[]{3, 5, 7};
    const int* cursor = values;
    const int* end = values + 3;
    int total = 0;
    while (cursor != end) {
        total += *cursor;
        ++cursor;
    }
    std::cout << total << '\n';
    assert(total == 15);
}

#include <cassert>
#include <iostream>
#include <vector>

long long sum_range(const std::vector<int>& values) {
    long long total = 0;
    for(auto cursor = values.begin(); cursor != values.end(); ++cursor)
        total += *cursor;
    return total;
}

int main() {
    assert(sum_range({3,5,7}) == 15);
    assert(sum_range({}) == 0);
    assert(sum_range({-4,4}) == 0);
    std::cout << "nonempty=" << sum_range({3,5,7}) << " empty=" << sum_range({}) << '\n';
}
